#include <iostream>
using namespace std;

int main() {
    cout << 7 / 2 << endl;
    unsigned char c = 250;
    c += 10;
    cout << static_cast<int>(c) << endl;
    return 0;
}

#include <cmath>
#include <iostream>
using namespace std;

int main() {
    double a = 0.1 + 0.2;
    cout << boolalpha << (a == 0.3) << endl;
    cout << (fabs(a - 0.3) < 1e-9) << endl;
    return 0;
}

